import math


def evaluate(expr: str) -> int:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            start = i
            while i < n and '0' <= expr[i] <= '9':
                i += 1
            tokens.append(int(expr[start:i]))
        elif c in '+-*/%^!()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    expanded = []
    for tok in tokens:
        if tok == '(' and expanded and (type(expanded[-1]) is int or expanded[-1] in (')', '!')):
            expanded.append('*')
        expanded.append(tok)
    tokens = expanded

    pos = 0
    length = len(tokens)

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while pos < length and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_mul()
            if op == '+':
                val += right
            else:
                val -= right
        return val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < length and tokens[pos] in ('*', '/', '%'):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == '*':
                val *= right
            else:
                if right == 0:
                    raise ValueError("Division or remainder by zero")
                q = abs(val) // abs(right)
                if (val < 0) ^ (right < 0):
                    q = -q
                if op == '/':
                    val = q
                else:
                    val = val - q * right
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while pos < length and tokens[pos] == '-':
            neg = not neg
            pos += 1
        val = parse_pow()
        return -val if neg else val

    def parse_pow() -> int:
        nonlocal pos
        val = parse_post()
        if pos < length and tokens[pos] == '^':
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            val = val ** exp
        return val

    def parse_post() -> int:
        nonlocal pos
        val = parse_primary()
        while pos < length and tokens[pos] == '!':
            pos += 1
            if val < 0:
                raise ValueError("Factorial of negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        nonlocal pos
        if pos >= length:
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        if type(tok) is int:
            pos += 1
            return tok
        if tok == '(':
            pos += 1
            val = parse_add()
            if pos >= length or tokens[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_add()
    if pos != length:
        raise ValueError(f"Unexpected trailing token: {tokens[pos]!r}")
    return result
